    46→function parseEvalIds(str) {
    47→  const ids = [];
    48→  for (const part of str.split(",")) {
    49→    const range = part.match(/^(\d+)-(\d+)$/);
    50→    if (range) {
    51→      const start = parseInt(range[1], 10);
    52→      const end = parseInt(range[2], 10);
    53→      for (let i = start; i <= end; i++) ids.push(i);
    54→    } else {
    55→      ids.push(Number(part));
    56→    }
    57→  }
    58→  return ids;
    59→}
