   158→
   159→  const worktreePath = args.gradeOnly ? null : setupWorktree(repoRoot);
   160→
   161→  try {
   162→    if (!args.gradeOnly) {
   163→      await generateResponses(evals, worktreePath, iterationDir, args);
   164→    }
   165→    await gradeResponses(evals, iterationDir, args);
