   178→function setupWorktree(repoRoot) {
   179→  const worktreePath = path.join(
   180→    require("os").tmpdir(),
   181→    `eval-run-${Date.now()}`
   182→  );
   183→  log("Creating clean worktree at:", worktreePath);
   184→
   185→  execSync(`git worktree add --detach "${worktreePath}" HEAD`, {
   186→    cwd: repoRoot,
   187→    stdio: "inherit",
   188→  });
   189→
   190→  // Remove docs/ (contains experiment ideal answers and spec documents
   191→  // that describe eval strategy and known weaknesses)
   192→  const docsDir = path.join(worktreePath, "docs");
   193→  if (fs.existsSync(docsDir)) {
   194→    fs.rmSync(docsDir, { recursive: true });
   195→    log("Removed docs/ for contamination isolation");
   196→  }
   197→
   198→  // Remove eval definitions (assertions are the answer key)
   199→  const evalsFile = path.join(worktreePath, EVALS_PATH);
   200→  if (fs.existsSync(evalsFile)) {
   201→    fs.rmSync(evalsFile);
   202→    log("Removed evals.json for contamination isolation");
   203→  }
   204→
   205→  // Remove prior iteration outputs to prevent contamination
   206→  // (response.md files contain model answers to the same eval prompts)
   207→  const workspaceDir = path.join(worktreePath, "skills-workspace");
   208→  if (fs.existsSync(workspaceDir)) {
   209→    for (const entry of fs.readdirSync(workspaceDir)) {
   210→      if (entry.startsWith("iteration-")) {
   211→        fs.rmSync(path.join(workspaceDir, entry), { recursive: true });
   212→      }
   213→    }
   214→    log("Removed prior iteration outputs for contamination isolation");
   215→  }
   216→
   217→  return worktreePath;
   218→}
