   231→function runClaude({ prompt, systemPrompt, model, cwd, pluginDir, timeoutMs = 600000 }) {
   232→  return new Promise((resolve, reject) => {
   233→    let settled = false;
   234→    const settle = (fn, value) => {
   235→      if (settled) return;
   236→      settled = true;
   237→      fn(value);
   238→    };
   239→
   240→    const args = ["--print", "--output-format", "stream-json", "--verbose", "--model", model];
   241→
   242→    args.push("--no-session-persistence", "--setting-sources", "");
   243→
   244→    if (pluginDir) {
   245→      args.push("--plugin-dir", pluginDir);
   246→    }
   247→    if (systemPrompt) {
   248→      args.push("--system-prompt", systemPrompt);
   249→    }
   250→    args.push("-p", prompt);
   251→
   252→    let stdout = "";
   253→    let stderr = "";
   254→
   255→    const proc = spawn("claude", args, {
   256→      cwd,
   257→      env: { ...process.env },
   258→      stdio: ['ignore', 'pipe', 'pipe'],
   259→    });
   260→
   261→    const timer = setTimeout(() => {
   262→      proc.kill("SIGTERM");
   263→      settle(reject, new Error(`Timed out after ${timeoutMs}ms`));
   264→    }, timeoutMs);
   265→
   266→    proc.stdout.on("data", (data) => { stdout += data; });
   267→    proc.stderr.on("data", (data) => { stderr += data; });
   268→
   269→    proc.on("close", (code) => {
   270→      clearTimeout(timer);
   271→      if (code !== 0) {
   272→        const err = new Error(`claude exited with code ${code}:\n  stderr: ${stderr.slice(0, 500)}`);
   273→        err.stdout = stdout;
   274→        err.stderr = stderr;
   275→        settle(reject, err);
   276→        return;
   277→      }
   278→      try {
   279→        const lines = stdout.split("\n").filter(l => l.trim());
   280→        const parsed = lines.map(l => JSON.parse(l));
   281→        const resultLine = parsed.filter(o => o.type === "result").pop();
   282→        if (!resultLine) throw new Error("No result line found in stream-json output");
   283→        resultLine._conversationJsonl = stdout;
   284→        settle(resolve, resultLine);
   285→      } catch (e) {
   286→        settle(reject, new Error(`Failed to parse claude output: ${e.message}\n${stdout.slice(0, 500)}`));
   287→      }
   288→    });
   289→
   290→    proc.on("error", (err) => {
   291→      clearTimeout(timer);
   292→      settle(reject, err);
   293→    });
   294→  });
   295→}
