   297→async function generateResponses(evals, worktreePath, iterationDir, args) {
   298→  const configs = ["with_skill"];
   299→  if (args.baseline) configs.push("no_skill");
   300→
   301→  log(
   302→    `\nGenerating responses (${configs.join(", ")}, parallel=${args.parallel})...`
   303→  );
   304→
   305→  const jobs = [];
   306→  for (const evalDef of evals) {
   307→    for (const config of configs) {
   308→      jobs.push({ evalDef, config });
   309→    }
   310→  }
   311→
   312→  const totalJobs = jobs.length;
   313→  let completedJobs = 0;
   314→  const startTime = Date.now();
   315→
   316→  for (let i = 0; i < jobs.length; i += args.parallel) {
   317→    const batch = jobs.slice(i, i + args.parallel);
   318→    const batchNum = Math.floor(i / args.parallel) + 1;
   319→    const totalBatches = Math.ceil(jobs.length / args.parallel);
   320→    const elapsed = ((Date.now() - startTime) / 1000).toFixed(0);
   321→    log(`  [batch ${batchNum}/${totalBatches}, ${completedJobs}/${totalJobs} done, ${elapsed}s elapsed]`);
   322→
   323→    await Promise.all(
   324→      batch.map(({ evalDef, config }) =>
   325→        generateOne(evalDef, config, worktreePath, iterationDir, args.model)
   326→      )
   327→    );
   328→    completedJobs += batch.length;
   329→  }
   330→}
