   332→async function generateOne(evalDef, config, worktreePath, iterationDir, model) {
   333→  const evalDir = path.join(
   334→    iterationDir,
   335→    `eval-${evalDef.id}-${evalDef.slug}`,
   336→    config
   337→  );
   338→  fs.mkdirSync(path.join(evalDir, "outputs"), { recursive: true });
   339→
   340→  // Skip if already completed (enables resuming interrupted runs)
   341→  const timingPath = path.join(evalDir, "timing.json");
   342→  if (fs.existsSync(timingPath)) {
   343→    try {
   344→      const existing = JSON.parse(fs.readFileSync(timingPath, "utf-8"));
   345→      if (existing.duration_ms != null && !existing.error) {
   346→        log(`  ⏭ Eval ${evalDef.id} [${config}] — already completed, skipping`);
   347→        return;
   348→      }
   349→    } catch { /* re-run if timing.json is corrupt */ }
   350→  }
   351→
   352→  log(`  Running eval ${evalDef.id} (${evalDef.slug}) [${config}]...`);
   353→
   354→  try {
   355→    const result = await runClaude({
   356→      prompt: evalDef.prompt,
   357→      model,
   358→      cwd: worktreePath,
   359→      pluginDir: config === "with_skill" ? worktreePath : undefined,
   360→      timeoutMs: evalDef.timeout_ms,
   361→    });
   362→
   363→    fs.writeFileSync(
   364→      path.join(evalDir, "outputs", "response.md"),
   365→      result.result || "",
   366→      "utf-8"
   367→    );
   368→
   369→    const usage = result.usage || {};
   370→    const timing = {
   371→      duration_ms: result.duration_ms || 0,
   372→      input_tokens: usage.input_tokens || 0,
   373→      output_tokens: usage.output_tokens || 0,
   374→      cache_creation_input_tokens: usage.cache_creation_input_tokens || 0,
   375→      cache_read_input_tokens: usage.cache_read_input_tokens || 0,
   376→      total_tokens:
   377→        (usage.input_tokens || 0) +
   378→        (usage.output_tokens || 0) +
   379→        (usage.cache_creation_input_tokens || 0) +
   380→        (usage.cache_read_input_tokens || 0),
   381→      cost_usd: result.total_cost_usd || 0,
   382→    };
   383→    fs.writeFileSync(
   384→      path.join(evalDir, "timing.json"),
   385→      JSON.stringify(timing, null, 2),
   386→      "utf-8"
   387→    );
   388→
   389→    if (result._conversationJsonl) {
   390→      fs.writeFileSync(
   391→        path.join(evalDir, "conversation.jsonl"),
   392→        result._conversationJsonl,
   393→        "utf-8"
   394→      );
   395→    }
   396→
   397→    log(
   398→      `  ✓ Eval ${evalDef.id} [${config}] — ${timing.total_tokens} tokens, ${timing.duration_ms}ms`
   399→    );
   400→  } catch (err) {
   401→    logError(`  ✗ Eval ${evalDef.id} [${config}] — ${err.message}`);
   402→    // Write error details for debugging
   403→    let errorLog = `${new Date().toISOString()}\n${err.message}\n${err.stack || ""}\n`;
   404→    if (err.stderr) errorLog += `\n--- stderr ---\n${err.stderr}\n`;
   405→    if (err.stdout) errorLog += `\n--- stdout (partial conversation trace) ---\n${err.stdout}\n`;
   406→    fs.writeFileSync(path.join(evalDir, "error.log"), errorLog, "utf-8");
   407→
   408→    // Save partial conversation trace even on failure
   409→    if (err.stdout) {
   410→      fs.writeFileSync(path.join(evalDir, "conversation.jsonl"), err.stdout, "utf-8");
   411→    }
   412→    fs.writeFileSync(
   413→      path.join(evalDir, "outputs", "response.md"),
   414→      `ERROR: ${err.message}`,
   415→      "utf-8"
   416→    );
   417→    fs.writeFileSync(
   418→      path.join(evalDir, "timing.json"),
   419→      JSON.stringify({ error: err.message }, null, 2),
   420→      "utf-8"
   421→    );
   422→  }
   423→}
   424→
   425→function buildGradingPrompt(evalDef, response) {
   426→  const assertionsList = evalDef.assertions
   427→    .map((a) => `- [${a.id}] ${a.text}`)
   428→    .join("\n");
   429→
   430→  return `## Assertions
   431→
   432→${assertionsList}
   433→
   434→## Expected Output Description
   435→
   436→${evalDef.expected_output}
   437→
   438→## Model Response
   439→
   440→${response}`;
   441→}
   442→
   443→async function gradeOne(evalDef, config, iterationDir, model, gradingSuffix = null) {
   444→  const evalDir = path.join(
   445→    iterationDir,
   446→    `eval-${evalDef.id}-${evalDef.slug}`,
   447→    config
   448→  );
   449→  const responsePath = path.join(evalDir, "outputs", "response.md");
   450→
   451→  if (!fs.existsSync(responsePath)) {
   452→    log(`  Skipping eval ${evalDef.id} [${config}] — no response`);
   453→    return;
   454→  }
   455→
   456→  const response = fs.readFileSync(responsePath, "utf-8");
   457→  if (response.startsWith("ERROR:")) {
   458→    log(`  Skipping eval ${evalDef.id} [${config}] — generation error`);
   459→    return;
   460→  }
   461→
   462→  log(`  Grading eval ${evalDef.id} (${evalDef.slug}) [${config}]...`);
   463→
   464→  const gradingPrompt = buildGradingPrompt(evalDef, response);
   465→
   466→  const result = await runClaude({
   467→    prompt: gradingPrompt,
   468→    systemPrompt: GRADING_SYSTEM_PROMPT,
   469→    model: model,
   470→    cwd: process.cwd(),
   471→  });
   472→
   473→  // Parse grading JSON from the response
   474→  const gradingText = result.result || "";
   475→  let grading;
   476→  try {
   477→    grading = JSON.parse(gradingText);
   478→  } catch {
   479→    // Try extracting JSON from markdown code fences
   480→    const fenceMatch = gradingText.match(/```(?:json)?\s*([\s\S]*?)```/);
   481→    if (fenceMatch) {
   482→      grading = JSON.parse(fenceMatch[1]);
   483→    } else {
   484→      // Try extracting the outermost JSON object (handles prose before/after)
   485→      const start = gradingText.indexOf("{");
   486→      const end = gradingText.lastIndexOf("}");
   487→      if (start !== -1 && end > start) {
   488→        grading = JSON.parse(gradingText.slice(start, end + 1));
   489→      } else {
   490→        throw new Error(
   491→          `Failed to parse grading JSON for eval ${evalDef.id}: ${gradingText.slice(0, 200)}`
   492→        );
   493→      }
   494→    }
   495→  }
   496→
   497→  // Add summary fields
   498→  grading.assertions_passed = grading.assertions.filter((a) => a.passed).length;
   499→  grading.assertions_total = grading.assertions.length;
   500→  grading.pass_rate =
   501→    grading.assertions_total > 0
   502→      ? grading.assertions_passed / grading.assertions_total
   503→      : 0;
   504→
   505→  const gradingFile = gradingSuffix ? `grading-${gradingSuffix}.json` : "grading.json";
   506→  fs.writeFileSync(
   507→    path.join(evalDir, gradingFile),
   508→    JSON.stringify(grading, null, 2),
   509→    "utf-8"
   510→  );
   511→
   512→  const status = grading.pass_rate === 1 ? "✓" : "✗";
   513→  log(
   514→    `  ${status} Eval ${evalDef.id} [${config}] — ${grading.assertions_passed}/${grading.assertions_total}`
   515→  );
   516→}
