   518→async function gradeResponses(evals, iterationDir, args) {
   519→  const configs = ["with_skill"];
   520→  if (args.baseline) configs.push("no_skill");
   521→
   522→  log(`\nGrading responses (model=${args.gradingModel}, parallel=${args.parallel})...`);
   523→
   524→  const jobs = [];
   525→  for (const evalDef of evals) {
   526→    for (const config of configs) {
   527→      jobs.push({ evalDef, config });
   528→    }
   529→  }
   530→
   531→  for (let i = 0; i < jobs.length; i += args.parallel) {
   532→    const batch = jobs.slice(i, i + args.parallel);
   533→    await Promise.all(
   534→      batch.map(({ evalDef, config }) =>
   535→        gradeOne(evalDef, config, iterationDir, args.gradingModel, args.gradingSuffix).catch((err) => {
   536→          logError(`  ✗ Eval ${evalDef.id} [${config}] — GRADING FAILED: ${err.message}`);
   537→          // Write grading error details for debugging
   538→          const errDir = path.join(iterationDir, `eval-${evalDef.id}-${evalDef.slug}`, config);
   539→          if (fs.existsSync(errDir)) {
   540→            fs.writeFileSync(
   541→              path.join(errDir, "error.log"),
   542→              `${new Date().toISOString()}\nGRADING FAILED: ${err.message}\n${err.stack || ""}\n`,
   543→              "utf-8"
   544→            );
   545→          }
   546→        })
   547→      )
   548→    );
   549→  }
   550→}
   551→function aggregateResults(evals, iterationDir, args) {
   552→  const configs = ["with_skill"];
   553→  if (args.baseline) configs.push("no_skill");
   554→
   555→  const benchmark = {
