import org.junit.jupiter.api.Assertions.assertEquals
import org.tabletest.junit.TableTest

class ReisSingleTicketDiscountTest {

    // -------------------------------------------------------------------------
    // Discount percentage based on trips in the last 30 days
    // -------------------------------------------------------------------------

    @TableTest("""
        tripsInLast30Days | expectedDiscountPercent
        0                 | 0
        1                 | 0
        4                 | 0
        5                 | 5
        9                 | 5
        10                | 10
        14                | 10
        15                | 15
        19                | 15
        20                | 20
        24                | 20
        25                | 25
        29                | 25
        30                | 30
        34                | 30
        35                | 35
        39                | 35
        40                | 40
        41                | 40
        100               | 40
    """)
    fun `adult discount percentage by trips in last 30 days`(
        tripsInLast30Days: Int,
        expectedDiscountPercent: Int,
    ) {
        val discount = ReisDiscount.forAdult(tripsInLast30Days)
        assertEquals(expectedDiscountPercent, discount.percent)
    }

    @TableTest("""
        tripsInLast30Days | expectedDiscountPercent
        0                 | 0
        1                 | 0
        4                 | 0
        5                 | 5
        10                | 10
        20                | 20
        40                | 40
        99                | 40
    """)
    fun `senior discount percentage by trips in last 30 days`(
        tripsInLast30Days: Int,
        expectedDiscountPercent: Int,
    ) {
        val discount = ReisDiscount.forSenior(tripsInLast30Days)
        assertEquals(expectedDiscountPercent, discount.percent)
    }

    // -------------------------------------------------------------------------
    // Children always get a flat 20% discount
    // -------------------------------------------------------------------------

    @TableTest("""
        tripsInLast30Days | expectedDiscountPercent
        0                 | 20
        1                 | 20
        4                 | 20
        5                 | 20
        10                | 20
        40                | 20
        100               | 20
    """)
    fun `child discount is always 20 percent regardless of travel history`(
        tripsInLast30Days: Int,
        expectedDiscountPercent: Int,
    ) {
        val discount = ReisDiscount.forChild(tripsInLast30Days)
        assertEquals(expectedDiscountPercent, discount.percent)
    }

    // -------------------------------------------------------------------------
    // Final ticket price after discount
    // -------------------------------------------------------------------------

    @TableTest("""
        passengerType | tripsInLast30Days | basePrice | expectedPrice
        adult         | 0                 | 100       | 100
        adult         | 4                 | 100       | 100
        adult         | 5                 | 100       | 95
        adult         | 10                | 100       | 90
        adult         | 20                | 100       | 80
        adult         | 40                | 100       | 60
        senior        | 5                 | 100       | 95
        senior        | 40                | 100       | 60
        child         | 0                 | 100       | 80
        child         | 40                | 100       | 80
    """)
    fun `ticket price after discount applied`(
        passengerType: PassengerType,
        tripsInLast30Days: Int,
        basePrice: Int,
        expectedPrice: Int,
    ) {
        val price = TicketPricing.singleTicketPrice(passengerType, tripsInLast30Days, basePrice)
        assertEquals(expectedPrice, price)
    }

    // -------------------------------------------------------------------------
    // Discount does not apply to non-single tickets or passenger types
    // that do not qualify for the Reis scheme
    // -------------------------------------------------------------------------

    @TableTest("""
        passengerType | tripsInLast30Days | basePrice | expectedPrice
        adult         | 5                 | 50        | 47
        adult         | 10                | 50        | 45
        adult         | 40                | 50        | 30
        child         | 0                 | 50        | 40
        senior        | 15                | 50        | 42
    """)
    fun `ticket price rounds correctly for non-round base prices`(
        passengerType: PassengerType,
        tripsInLast30Days: Int,
        basePrice: Int,
        expectedPrice: Int,
    ) {
        val price = TicketPricing.singleTicketPrice(passengerType, tripsInLast30Days, basePrice)
        assertEquals(expectedPrice, price)
    }

    // -------------------------------------------------------------------------
    // Rolling 30-day window: discount adjusts to current travel pattern
    // -------------------------------------------------------------------------

    @TableTest("""
        description                                | tripsInLast30Days | expectedDiscountPercent
        consistent traveller (2x/week ~8/month)    | 8                 | 5
        consistent traveller (3x/week ~12/month)   | 12                | 10
        reduced travel drops discount tier         | 4                 | 0
        increased travel raises discount tier      | 25                | 25
        maximum frequent traveller                 | 40                | 40
    """)
    fun `discount reflects rolling 30-day travel pattern for adults`(
        @Suppress("UNUSED_PARAMETER") description: String,
        tripsInLast30Days: Int,
        expectedDiscountPercent: Int,
    ) {
        val discount = ReisDiscount.forAdult(tripsInLast30Days)
        assertEquals(expectedDiscountPercent, discount.percent)
    }

    // -------------------------------------------------------------------------
    // Discount ladder boundary values
    // -------------------------------------------------------------------------

    @TableTest("""
        tripsInLast30Days | expectedTier
        0                 | 0
        4                 | 0
        5                 | 1
        9                 | 1
        10                | 2
        39                | 7
        40                | 8
        999               | 8
    """)
    fun `discount tier is capped at 8 (40 percent)`(
        tripsInLast30Days: Int,
        expectedTier: Int,
    ) {
        val tier = ReisDiscount.tierFor(tripsInLast30Days)
        assertEquals(expectedTier, tier)
    }
}

